<?php
declare(strict_types=1);
namespace VCX\Parity;
final class Structure {
    private Store $s;
    public function __construct(private ControlTower $app){$this->s=$app->s;}
    public static function version(array $tasks): string {usort($tasks,fn($a,$b)=>strcmp($a['Task_ID'],$b['Task_ID']));return Store::json(array_map(fn($t)=>[$t['Task_ID'],$t['Project_ID'],$t['Parent_Task_ID']??'',(string)($t['Sort_Order']??''),$t['Task_Type']],$tasks));}
    private function fullVersion(array $tasks): string {usort($tasks,fn($a,$b)=>strcmp($a['Task_ID'],$b['Task_ID']));return hash('sha256',Store::json(array_map(fn($t)=>array_map(fn($k)=>(string)($t[$k]??''),$this->s->columns('TASKS')),$tasks)));}
    private function key(string $id,string $opId): string{return 'CR002_STRUCTURE_OP_'.hash('sha256',$id.'|'.$opId);}
    public static function plan(array $tasks,array $projects,array $cmd): array {
        Store::check(is_array($cmd['taskIds']??null)&&count($cmd['taskIds'])>0&&count($cmd['taskIds'])<=300,'Chọn 1–300 task.');$map=array_column($tasks,null,'Task_ID');$selected=array_fill_keys($cmd['taskIds'],true);Store::check(count($selected)===count($cmd['taskIds'])&&!array_diff($cmd['taskIds'],array_keys($map)),'Task selection không hợp lệ.');
        $groups=[];$orders=[];foreach($tasks as$t){$parent=$t['Parent_Task_ID']??'';$key=Store::json([$parent,$t['Sort_Order']]);Store::check(preg_match('/^[1-9][0-9]*$/D',$t['Sort_Order'])&&(float)$t['Sort_Order']<=9007199254740991&&!isset($orders[$key]),'Existing Sort_Order invalid; repair separately.');$orders[$key]=true;$groups[$parent][]=$t;}
        foreach($groups as&$g)usort($g,fn($a,$b)=>(float)$a['Sort_Order']<=>(float)$b['Sort_Order']?:strcmp($a['Task_ID'],$b['Task_ID']));unset($g);
        $ordered=[];$visit=function($parent)use(&$visit,&$ordered,$groups){foreach($groups[$parent]??[]as$t){$ordered[]=$t;$visit($t['Task_ID']);}};$visit('');
        $roots=[];foreach($ordered as$t){if(!isset($selected[$t['Task_ID']]))continue;$parent=$t['Parent_Task_ID'];$ancestor=false;while($parent!==''){if(isset($selected[$parent])){$ancestor=true;break;}$parent=$map[$parent]['Parent_Task_ID']??'';}if(!$ancestor)$roots[]=$t;}Store::check(count($roots)>0,'Không có task để di chuyển.');
        $parent=$roots[0]['Parent_Task_ID'];$rootIds=array_column($roots,'Task_ID');$action=$cmd['action']??'';$destination=[];$insert=0;
        if(in_array($action,['up','down','indent','outdent'],true)){
            foreach($roots as$t)Store::check($t['Parent_Task_ID']===$parent,'Chọn task cùng sibling group.');$siblings=$groups[$parent]??[];$siblingIds=array_column($siblings,'Task_ID');$positions=array_map(fn($id)=>array_search($id,$siblingIds,true),$rootIds);foreach($positions as$i=>$pos)Store::check($i===0||$pos===$positions[$i-1]+1,'Chọn một nhóm task liên tiếp.');$first=$positions[0];$last=$positions[count($positions)-1];
            if($action==='up'||$action==='down'){Store::check($action==='up'?$first>0:$last<count($siblings)-1,'Đã ở đầu/cuối nhóm sibling.');$destination=ControlTower::filter($siblings,fn($t)=>!in_array($t['Task_ID'],$rootIds,true));$insert=$action==='up'?$first-1:$first+1;}
            elseif($action==='indent'){$previous=null;foreach(array_reverse(array_slice($siblings,0,$first))as$t)if($t['Task_Type']!=='MILESTONE'){$previous=$t;break;}Store::check($previous,'Không có task trước đủ điều kiện indent.');$parent=$previous['Task_ID'];$destination=$groups[$parent]??[];$insert=count($destination);}
            else{$oldParent=$map[$parent]??null;Store::check($oldParent,'Task root không thể outdent.');$parent=$oldParent['Parent_Task_ID'];$destination=ControlTower::filter($groups[$parent]??[],fn($t)=>!in_array($t['Task_ID'],$rootIds,true));$insert=array_search($oldParent['Task_ID'],array_column($destination,'Task_ID'),true)+1;}
        }elseif($action==='reparent'){
            Store::check(count($roots)===1,'Reparent chỉ chọn một task.');$parent=(string)($cmd['parentId']??'');Store::check($parent===''||isset($map[$parent]),'Parent không hợp lệ.');$destination=ControlTower::filter($groups[$parent]??[],fn($t)=>!in_array($t['Task_ID'],$rootIds,true));$insert=count($destination);
        }elseif(in_array($action,['before','after','inside'],true)){
            $anchor=$map[$cmd['anchorId']??'']??null;Store::check($anchor&&!in_array($anchor['Task_ID'],$rootIds,true),'Drop target không hợp lệ.');$parent=$action==='inside'?$anchor['Task_ID']:$anchor['Parent_Task_ID'];$destination=ControlTower::filter($groups[$parent]??[],fn($t)=>!in_array($t['Task_ID'],$rootIds,true));$insert=$action==='inside'?count($destination):array_search($anchor['Task_ID'],array_column($destination,'Task_ID'),true)+($action==='after'?1:0);
        }else Store::check(false,'Structural action không hợp lệ.');
        Store::check(!preg_match('/^\s*[-=+@]/',$parent),'Parent ID không an toàn để ghi Sheets.');if($parent!=='')Store::check($map[$parent]['Task_Type']!=='MILESTONE','MILESTONE không chứa children.');foreach($roots as$t)Store::check($t['Task_Type']!=='PHASE'||$parent==='','PHASE chỉ ở root.');
        array_splice($destination,$insert,0,$roots);$after=$map;foreach($roots as$t)$after[$t['Task_ID']]['Parent_Task_ID']=$parent;
        $left=$insert?(float)$destination[$insert-1]['Sort_Order']:0;$right=$insert+count($roots)<count($destination)?(float)$destination[$insert+count($roots)]['Sort_Order']:null;$step=$right===null?1024:floor(($right-$left)/(count($roots)+1));
        if($step>=1&&$left+$step*count($roots)<=9007199254740991){foreach($roots as$i=>$t)$after[$t['Task_ID']]['Sort_Order']=(string)(int)($left+$step*($i+1));}else{foreach($destination as$i=>$t)$after[$t['Task_ID']]['Sort_Order']=(string)(($i+1)*1024);}
        $errors=ControlTower::hierarchy(array_values($after),$projects);Store::check(!$errors,'Hierarchy: '.implode(', ',$errors));$seen=[];$changes=[];
        foreach($after as$id=>$t){$key=Store::json([$t['Parent_Task_ID'],$t['Sort_Order']]);Store::check(!isset($seen[$key]),'Sort_Order không hợp lệ/trùng.');$seen[$key]=true;if($t['Parent_Task_ID']!==$map[$id]['Parent_Task_ID']||$t['Sort_Order']!==$map[$id]['Sort_Order'])$changes[]=[$t['Task_ID'],$map[$id]['Parent_Task_ID'],$map[$id]['Sort_Order'],$t['Parent_Task_ID'],$t['Sort_Order']];}return$changes;
    }
    public function change(array $a,string $id,array $cmd,mixed $clientSchema='UNIFIED_TASKS_V2'): array {
        $this->s->db->exec('SAVEPOINT structure_call');try{return$this->changeLocked($a,$id,$cmd,$clientSchema);}catch(\Throwable $e){$this->s->db->exec('ROLLBACK TO SAVEPOINT structure_call');$this->s->invalidate();$message=$e instanceof \PDOException?'Database structural write failed.':$e->getMessage();return['ok'=>false,'code'=>str_starts_with($message,'CONFLICT')?'CONFLICT':($this->s->activeStructure()?'RECOVERY_REQUIRED':'VALIDATION'),'error'=>$message];}
    }
    private function changeLocked(array $a,string $id,array $cmd,mixed $clientSchema): array {
        Store::check($clientSchema==='UNIFIED_TASKS_V2'&&$this->s->unified(),'UNIFIED_TASKS_V2 required.');$this->app->edit($a,$id);Store::check(is_string($cmd['opId']??null)&&preg_match('/^[a-zA-Z0-9-]{16,100}$/D',$cmd['opId']),'Operation ID không hợp lệ.');$key=$this->key($id,$cmd['opId']);$stored=$this->s->find('CONFIG',$key);
        if($stored){$j=json_decode($stored['Value'],true,512,JSON_THROW_ON_ERROR);Store::check($j['projectId']===$id&&$j['actorId']===$a['User_ID'],'Operation ID thuộc actor khác.');$r=$this->recoverLocked($a,$id,$cmd['opId'],'RESUME');if($r['status']==='ROLLED_BACK')return['ok'=>false,'code'=>'ROLLED_BACK','error'=>'Thao tác đã rollback; chọn lệnh mới.','detail'=>$r['detail']];return['ok'=>true,'opId'=>$cmd['opId'],'detail'=>$r['detail']];}
        Store::check(!$this->s->activeStructure(),'STRUCTURE_RECOVERY_REQUIRED: recover existing operation first.');$tasks=$this->app->projectRows('TASKS',$id);$errors=ControlTower::hierarchy($tasks,$this->s->rows('PROJECTS'));Store::check(!$errors,'Existing hierarchy invalid.');
        if(($cmd['baseVersion']??null)!==self::version($tasks))return['ok'=>false,'code'=>'CONFLICT','error'=>'CONFLICT: hierarchy đã thay đổi; đối chiếu trước khi di chuyển.'];
        try{$changes=self::plan($tasks,$this->s->rows('PROJECTS'),$cmd);}catch(\RuntimeException $e){return['ok'=>false,'code'=>'VALIDATION','error'=>$e->getMessage()];}
        $patches=array_column($changes,null,0);$after=array_map(function($t)use($patches){if(isset($patches[$t['Task_ID']])){$p=$patches[$t['Task_ID']];$t['Parent_Task_ID']=$p[3];$t['Sort_Order']=$p[4];}return$t;},$tasks);
        $journal=['opId'=>$cmd['opId'],'projectId'=>$id,'actorId'=>$a['User_ID'],'status'=>'PREPARED','changes'=>$changes,'beforeFullVersion'=>$this->fullVersion($tasks),'afterFullVersion'=>$this->fullVersion($after)];Store::check(ControlTower::length(Store::json($journal))<45000,'Structural journal quá lớn; tách nhóm nhỏ hơn.');
        $this->s->audit($a,'TASKS',$id,'STRUCTURE_INTENT',[],['opId'=>$cmd['opId'],'action'=>$cmd['action'],'changes'=>$changes]);$this->s->config($key,Store::json($journal));$r=$this->recoverLocked($a,$id,$cmd['opId'],'RESUME');if($r['status']==='ROLLED_BACK')return['ok'=>false,'code'=>'ROLLED_BACK','error'=>'Thao tác đã rollback; chọn lệnh mới.','detail'=>$r['detail']];return['ok'=>true,'opId'=>$cmd['opId'],'detail'=>$r['detail']];
    }
    public function recover(array $a,string $id,string $opId,string $decision,mixed $clientSchema='UNIFIED_TASKS_V2'): array {
        $this->s->db->exec('SAVEPOINT recovery_call');try{Store::check($clientSchema==='UNIFIED_TASKS_V2'&&$this->s->unified(),'UNIFIED_TASKS_V2 required.');return$this->recoverLocked($a,$id,$opId,$decision);}catch(\Throwable $e){$this->s->db->exec('ROLLBACK TO SAVEPOINT recovery_call');$this->s->invalidate();return['ok'=>false,'code'=>'RECOVERY_REQUIRED','error'=>$e instanceof \PDOException?'Database recovery write failed.':$e->getMessage()];}
    }
    private function recoverLocked(array $a,string $id,string $opId,string $decision): array {
        $this->app->edit($a,$id);Store::check($this->s->unified()&&in_array($decision,['RESUME','ROLLBACK'],true),'Recovery decision không hợp lệ.');$key=$this->key($id,$opId);$r=$this->s->find('CONFIG',$key);Store::check($r,'Journal không tồn tại.');$j=json_decode($r['Value'],true,512,JSON_THROW_ON_ERROR);Store::check($j['projectId']===$id&&($j['actorId']===$a['User_ID']||ControlTower::admin($a)),'Chỉ người tạo thao tác hoặc Admin được recover.');
        Store::check(in_array($j['status'],['PREPARED','COMPLETED','ROLLED_BACK'],true),'Invalid structural journal.');if($j['status']==='PREPARED'){
            $tasks=ControlTower::filter($this->s->rows('TASKS',true),fn($t)=>$t['Project_ID']===$id);$changes=array_column($j['changes'],null,0);$before=[];$target=[];
            foreach($tasks as$t){$b=$t;$out=$t;if(isset($changes[$t['Task_ID']])){$p=$changes[$t['Task_ID']];Store::check(in_array($t['Parent_Task_ID'],[$p[1],$p[3]],true)&&in_array($t['Sort_Order'],[$p[2],$p[4]],true),'RECOVERY_CONFLICT: unexpected structural data.');$b['Parent_Task_ID']=$p[1];$b['Sort_Order']=$p[2];$out['Parent_Task_ID']=$p[$decision==='ROLLBACK'?1:3];$out['Sort_Order']=$p[$decision==='ROLLBACK'?2:4];}$before[]=$b;$target[]=$out;}
            Store::check($this->fullVersion($before)===$j['beforeFullVersion'],'RECOVERY_CONFLICT: task data changed; do not overwrite.');Store::check(!ControlTower::hierarchy($target,$this->s->rows('PROJECTS')),'Recovery hierarchy invalid.');$update=$this->s->db->prepare('UPDATE tasks SET Parent_Task_ID=?,Sort_Order=? WHERE Task_ID=? AND Project_ID=?');foreach($target as$t)if(isset($changes[$t['Task_ID']])){Metrics::timed('database_write',fn()=>$update->execute([$t['Parent_Task_ID']===''?null:$t['Parent_Task_ID'],$t['Sort_Order'],$t['Task_ID'],$id]));Metrics::count('writes','TASKS');}$this->s->invalidate();Store::check($this->fullVersion(ControlTower::filter($this->s->rows('TASKS',true),fn($t)=>$t['Project_ID']===$id))===($decision==='ROLLBACK'?$j['beforeFullVersion']:$j['afterFullVersion']),'STRUCTURE_INTEGRITY_FAILED');$j['status']=$decision==='ROLLBACK'?'ROLLED_BACK':'COMPLETED';$this->s->config($key,Store::json($j));
        }
        $this->s->config('CR002_STRUCTURE_ACTIVE','');$this->s->config('DATABASE_SCHEMA_VERSION','UNIFIED_TASKS_V2');return['ok'=>true,'status'=>$j['status'],'detail'=>$this->app->detail($a,$id)];
    }
}
